import{_ as t,o,c as n,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse(`{"title":"I Don't See a Button","description":"Why controls can be missing in ApptiveGrid, and how to find the cause.","frontmatter":{"title":"I Don't See a Button","description":"Why controls can be missing in ApptiveGrid, and how to find the cause."},"headers":[],"relativePath":"en/fehlerbehebung/fehlende-schaltflaechen.md","filePath":"en/fehlerbehebung/fehlende-schaltflaechen.md","lastUpdated":1787319236000}`),r={name:"en/fehlerbehebung/fehlende-schaltflaechen.md"};function s(i,e,l,h,d,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="i-don-t-see-a-button" tabindex="-1">I Don&#39;t See a Button <a class="header-anchor" href="#i-don-t-see-a-button" aria-label="Permalink to &quot;I Don&#39;t See a Button&quot;">​</a></h1><p>&quot;It looks different on my screen than yours&quot; is one of the most common questions about ApptiveGrid. Usually there&#39;s no bug behind it.</p><div class="tip custom-block"><p class="custom-block-title">The basic principle</p><p>ApptiveGrid only shows a feature <strong>if you&#39;re allowed to use it</strong>. If you lack the permission, the button simply disappears — no error message, no grayed-out button.</p><p>For users without the necessary rights, the interface just looks cleaner.</p></div><h2 id="the-four-most-common-causes" tabindex="-1">The four most common causes <a class="header-anchor" href="#the-four-most-common-causes" aria-label="Permalink to &quot;The four most common causes&quot;">​</a></h2><h3 id="_1-·-your-role-in-the-space" tabindex="-1">1 · Your role in the Space <a class="header-anchor" href="#_1-·-your-role-in-the-space" aria-label="Permalink to &quot;1 · Your role in the Space&quot;">​</a></h3><p>The most common reason. Your <a href="/en/zusammenarbeit/rollen">role</a> determines what you see:</p><table tabindex="0"><thead><tr><th>Role</th><th>You won&#39;t see features for …</th></tr></thead><tbody><tr><td><strong>View</strong></td><td>Editing entries, changing the structure</td></tr><tr><td><strong>Edit</strong></td><td>Creating fields, views, forms, Flows</td></tr><tr><td><strong>Manage</strong></td><td>Changing the plan and seats</td></tr></tbody></table><p><strong>How to check:</strong> Open <strong>Share Space</strong>. Your role is shown in the <em>Shared with</em> list. If it&#39;s too low, ask someone with the <em>Manage</em> role, or the owner, to adjust it.</p><h3 id="_2-·-the-plan" tabindex="-1">2 · The plan <a class="header-anchor" href="#_2-·-the-plan" aria-label="Permalink to &quot;2 · The plan&quot;">​</a></h3><p>Some features are tied to your plan. In that case they&#39;re usually <strong>visible, but marked with an upgrade notice</strong> — for example, Pro steps in the Flow editor are marked <strong>Pro</strong>.</p><p>Click on the feature: if <em>Upgrade to unlock this feature</em> appears, it&#39;s the plan, not the role.</p><h3 id="_3-·-the-context" tabindex="-1">3 · The context <a class="header-anchor" href="#_3-·-the-context" aria-label="Permalink to &quot;3 · The context&quot;">​</a></h3><p>Some features only appear once their prerequisite is met:</p><table tabindex="0"><thead><tr><th>You&#39;re missing …</th><th>Prerequisite</th></tr></thead><tbody><tr><td><strong>Use linked value</strong> or <strong>Calculate sum</strong> among the column types</td><td>A <a href="/en/grids/verknuepfungen">link</a> must exist</td></tr><tr><td><strong>Calculate sum</strong></td><td>A column of type <em>Link multiple records</em></td></tr><tr><td>A usable Kanban view</td><td>A column of type <em>Single Select</em></td></tr><tr><td>Calendar view</td><td>A date field</td></tr><tr><td>Map view</td><td>A field of type <em>Address</em> or <em>Geolocation</em></td></tr><tr><td>Donut Chart block</td><td>A column of type <em>Single Select</em></td></tr><tr><td>Sum Card block</td><td>A numeric column in the view</td></tr><tr><td><strong>Share entry</strong></td><td>A form on this Grid</td></tr><tr><td>Sharing options for a page</td><td>A created portal link</td></tr></tbody></table><h3 id="_4-·-you-re-in-the-wrong-mode" tabindex="-1">4 · You&#39;re in the wrong mode <a class="header-anchor" href="#_4-·-you-re-in-the-wrong-mode" aria-label="Permalink to &quot;4 · You&#39;re in the wrong mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You&#39;re missing …</th><th>Check</th></tr></thead><tbody><tr><td>Editing features on a page</td><td>Are you in <em>Application</em> mode instead of <em>Editor</em> mode? Is <em>Lock page</em> active?</td></tr><tr><td>Block settings</td><td>Is <em>Structure mode</em> shown, and a block selected?</td></tr><tr><td>Columns in a view</td><td>Are they hidden via <em>hidden</em>?</td></tr><tr><td>Entries</td><td>Is the view filtering them out?</td></tr></tbody></table><h2 id="steps-to-narrow-it-down" tabindex="-1">Steps to narrow it down <a class="header-anchor" href="#steps-to-narrow-it-down" aria-label="Permalink to &quot;Steps to narrow it down&quot;">​</a></h2><ol><li><strong>Does a colleague with more rights see the feature?</strong> Then it&#39;s the role.</li><li><strong>Does an upgrade notice appear when you click?</strong> Then it&#39;s the plan.</li><li><strong>Is the feature also missing in a new, empty Grid?</strong> Then it&#39;s not the context.</li><li><strong>Are you in the right view and the right mode?</strong></li></ol><h2 id="typical-cases" tabindex="-1">Typical cases <a class="header-anchor" href="#typical-cases" aria-label="Permalink to &quot;Typical cases&quot;">​</a></h2><p><strong>&quot;I can&#39;t add a column.&quot;</strong> The <em>Edit</em> role allows editing entries, not the structure. You need <em>Manage</em>.</p><p><strong>&quot;I don&#39;t see the Flows section.&quot;</strong> Check both role and plan — the number of Flows depends on your plan.</p><p><strong>&quot;The switch on the Flow won&#39;t toggle.&quot;</strong> Only <em>Manage</em> and the owner may <a href="/en/flows/was-ist-ein-flow#switching-on-and-off">turn a Flow on or off</a>. With <em>Edit</em>, the switch is visible but locked.</p><p><strong>&quot;I can&#39;t create a form.&quot;</strong> Check your role; also, the number of forms per Space depends on your plan.</p><p><strong>&quot;The Use linked value column type is missing.&quot;</strong> There&#39;s no link in the Grid yet. Create a <em>Link record</em> field first.</p><p><strong>&quot;I can&#39;t change the plan.&quot;</strong> Only the owner can: <em>Only the owner can change the plan.</em></p><p><strong>&quot;My colleague sees more columns than I do.&quot;</strong> You&#39;re working in different views, or columns are hidden in your view. Hidden columns apply per view, not per person.</p><h2 id="if-none-of-this-applies" tabindex="-1">If none of this applies <a class="header-anchor" href="#if-none-of-this-applies" aria-label="Permalink to &quot;If none of this applies&quot;">​</a></h2><p>Sign out and back in — this occasionally helps with permissions changed shortly before. If that doesn&#39;t help either, the <strong>chat</strong> in the application (<em>Chat with us</em>) can help further.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/rollen">Roles</a></li><li><a href="/en/fehlerbehebung/haeufige-fehlermeldungen">Common Error Messages</a></li><li><a href="/en/ansichten/spalten-verwalten">Managing columns</a> — hidden columns</li></ul>',30)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
